library (polari_cnt_latch) {
  /* generated by cntfet.cnt_sequential — executor polari-own-loop.
     UNITS: time ps, capacitance fF. Transparent-high D latch (clatch,
     CELL_LIBRARY x1): setup/hold vs the G FALLING edge (bisection),
     D->Q = the transparent arc. G->Q (open) arc NOT characterized.
     INTRINSIC-grade, NOT signoff (plan D1). */
  delay_model : table_lookup;
  time_unit : "1ps";
  capacitive_load_unit (1, ff);
  voltage_unit : "1V";
  current_unit : "1uA";
  pulling_resistance_unit : "1kohm";
  leakage_power_unit : "1uW";
  nom_voltage : 0.6;
  nom_temperature : 300;
  nom_process : 1;
  cell (DLATCHX1) {
    latch (IQ, IQN) { enable : "G"; data_in : "D"; }
    pin (G) {
      direction : input; clock : true;
      capacitance : 0.010413;
    }
    pin (D) {
      direction : input;
      capacitance : 0.010413;
      timing () {
        related_pin : "G";
        timing_type : setup_falling;
        rise_constraint (scalar) { values ("0.31805"); }
        fall_constraint (scalar) { values ("0.31805"); }
      }
      timing () {
        related_pin : "G";
        timing_type : hold_falling;
        rise_constraint (scalar) { values ("-0.079512"); }
        fall_constraint (scalar) { values ("-0.079512"); }
      }
    }
    pin (Q) {
      direction : output;
      function : "IQ";
      timing () {
        related_pin : "D";
        timing_sense : positive_unate;
        cell_rise (scalar) { values ("0.69196"); }
        cell_fall (scalar) { values ("0.64758"); }
        rise_transition (scalar) { values ("0.35875"); }
        fall_transition (scalar) { values ("0.35868"); }
      }
    }
  }
}

library (polari_cnt_seq) {
  /* generated by cntfet.cnt_sequential — executor polari-own-loop.
     UNITS: time ps, capacitance fF. Scalar constraints at ONE declared
     slew/load point (bisection, resolution recorded in the run row).
     INTRINSIC-grade, x1 only. NOT signoff (plan D1). */
  delay_model : table_lookup;
  time_unit : "1ps";
  capacitive_load_unit (1, ff);
  voltage_unit : "1V";
  current_unit : "1uA";
  pulling_resistance_unit : "1kohm";
  leakage_power_unit : "1uW";
  nom_voltage : 0.6;
  nom_temperature : 300;
  nom_process : 1;
  cell (DFFX1) {
    ff (IQ, IQN) { next_state : "D"; clocked_on : "CLK"; }
    pin (CLK) {
      direction : input; clock : true;
      capacitance : 0.010413;
    }
    pin (D) {
      direction : input;
      capacitance : 0.010413;
      timing () {
        related_pin : "CLK";
        timing_type : setup_rising;
        rise_constraint (scalar) { values ("0.31805"); }
        fall_constraint (scalar) { values ("0.31805"); }
      }
      timing () {
        related_pin : "CLK";
        timing_type : hold_rising;
        rise_constraint (scalar) { values ("-0.079512"); }
        fall_constraint (scalar) { values ("-0.079512"); }
      }
    }
    pin (Q) {
      direction : output;
      function : "IQ";
      timing () {
        related_pin : "CLK";
        timing_type : rising_edge;
        timing_sense : non_unate;
        cell_rise (scalar) { values ("0.81126"); }
        cell_fall (scalar) { values ("1.088"); }
        rise_transition (scalar) { values ("0.54294"); }
        fall_transition (scalar) { values ("0.54046"); }
      }
    }
  }
}
